values ('bonds-chrome', 'coffee', 'bonds', 'bonds-chrome', 'blends', 'bag', '#6B4A33', 'قهوة كروم بلند', 'بلند بقوام غني وممتلئ وحموضة خفيفة: كراميل، شوكولاتة داكنة ومكسرات محمصة. حلوة سادة أو باللبن.', 225, '{"النكهات":"كراميل، شوكولاتة داكنة، مكسرات محمصة","القوام":"غني وممتلئ","الحموضة":"خفيفة","النوع":"بلند","الشكل":"حبوب كاملة"}'::jsonb, '[{"label":"250 جم","labelEn":"250 g","stock":20,"price":225,"opts":{"weight":"250 جم"}},{"label":"1 كجم","labelEn":"1 kg","stock":20,"price":900,"opts":{"weight":"1 كجم"}}]'::jsonb, 'live', 0, '[]'::jsonb, '[["مين بيحمص القهوة؟","بوندز لتحميص القهوة، شريكنا. القهوة جاية من المحمصة على طول، أصلية ومقفولة."],["حبوب ولا مطحونة؟","حبوب كاملة، علشان تفضل طازة لحد ما تطحنها قبل التحضير."],["أحفظها إزاي؟","في الكيس مقفول، في مكان ناشف بعيد عن الشمس والتلاجة. أحلى طعم خلال 4 أسابيع من الفتح."]]'::jsonb, '{"name":"Chrome Blend","lead":"A blend with a full, rich body and mild acidity: caramel, dark chocolate and roasted nuts. Great black or with milk.","attributes":{"Tasting notes":"Caramel, dark chocolate, roasted nuts","Body":"Full and rich","Acidity":"Mild","Type":"Blend","Form":"Whole beans"},"faq":[["Who roasts the coffee?","Bonds Coffee Roasters, our partner. The coffee comes straight from the roastery, original and sealed."],["Beans or ground?","Whole beans, so they stay fresh until you grind them just before brewing."],["How do I store it?","In the closed bag, somewhere dry, away from sunlight and the fridge. Best within 4 weeks of opening."]]}'::jsonb)
